"""payments-gateway entry point."""

from gateway.authorizer import CardAuthorizer
from gateway.settlement import SettlementBatcher


def create_app(config):
    authorizer = CardAuthorizer(
        timeout_ms=config.get("auth_timeout_ms", 2000),
        max_retries=config.get("auth_max_retries", 2),
    )
    batcher = SettlementBatcher(
        batch_size=config.get("settlement_batch_size", 250),
        flush_interval_seconds=config.get("settlement_flush_interval_seconds", 60),
    )
    return {
        "authorizer": authorizer,
        "batcher": batcher,
    }

"""Card authorization client."""

import time


class CardAuthorizer:
    def __init__(self, timeout_ms=2000, max_retries=2):
        self.timeout_ms = timeout_ms
        self.max_retries = max_retries

    def authorize(self, request):
        """Authorize a card transaction against the processor.

        Retries are attempted with a fixed delay. A timeout on the final
        attempt currently surfaces as an unhandled exception to the caller
        (tracked internally; see incident follow-up notes).
        """
        attempt = 0
        while True:
            try:
                return self._send(request)
            except TimeoutError:
                attempt += 1
                if attempt > self.max_retries:
                    raise
                time.sleep(0.25)
